import pandas as pd

cols = []
for d in cols_alim:
    for k, v in d.items():
        cols += v
cols = [c for c in dict.fromkeys(cols) if c in tableau.columns]

groupes = {}
for c in cols:
    groupes.setdefault(c.split('_')[0], []).append(c)

resultats = []
for prefixe, cs in groupes.items():
    sub = tableau[cs].apply(pd.to_numeric, errors='coerce')
    mesure = sub.notna().any(axis=1)
    positif = (sub >= 0.3).any(axis=1)
    n_mes = int(mesure.sum())
    n_pos = int(positif.sum())
    if n_mes >= 30:
        resultats.append((prefixe, n_pos, n_mes, round(100 * n_pos / n_mes, 1)))

resultats.sort(key=lambda x: x[1], reverse=True)
for r in resultats[:10]:
    print(r)

